/** Output names of a SELECT's top-level select list, in order. */
function selectListNames(body: string): string[] {
	const parser = new Parser();
	const database = dbConfig.dialect === Dialect.Postgres ? 'postgresql' : 'sqlite';
	const ast = parser.astify(body, { database }) as unknown as {
		columns: { as: string | null; expr: { column?: string | { expr: { value: string } } } }[];
	};
	return ast.columns.map((column) => column.as ?? columnName(column.expr.column));
}

function columnName(column: string | { expr: { value: string } } | undefined): string {
	if (typeof column === 'string') {
		return column;
	}
	return column?.expr?.value ?? '';
}

